'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const life=require('../../../collectors/nodered/live-integration/lifecycle');
test('all closers run once before and after late registration',()=>{const c=life.create(),seen=[];c.add(()=>{seen.push('first');throw Error('controlled');});c.add(()=>seen.push('producer'));c.add(()=>seen.push('exporter'));c.close();c.close();c.add(()=>seen.push('late'));assert.deepEqual(seen,['first','producer','exporter','late']);assert.equal(c.closed(),true);});
test('startup requires a matching live first checked epoch',()=>{const deadline=require('node:perf_hooks').performance.now()+1000;assert.doesNotThrow(()=>life.requireEpoch({epoch:1n,allowed:true,deadline},'1'));for(const x of [undefined,{}, {epoch:2n,allowed:true,deadline},{epoch:1,allowed:true,deadline},{epoch:1n,allowed:false,deadline},{epoch:1n,allowed:true,deadline:0}])assert.throws(()=>life.requireEpoch(x,'1'));});
test('lost, expired and mismatched initial permits fail before startup',async()=>{const valid={epoch:1n,allowed:true,deadline:require('node:perf_hooks').performance.now()+1000};await life.awaitFirst({ready:Promise.resolve(),authority:()=>valid},'1',50);await assert.rejects(life.awaitFirst({ready:Promise.reject(Error('closed')),authority:()=>valid},'1',50));await assert.rejects(life.awaitFirst({ready:new Promise(()=>{}),authority:()=>valid},'1',10));await assert.rejects(life.awaitFirst({ready:Promise.resolve(),authority:()=>({...valid,epoch:2n})},'1',50));});
